#import <UIKit/UIKit.h>
@interface VocabController : UITableViewController <UITextFieldDelegate,UIAlertViewDelegate> {
 NSMutableArray *_books; NSMutableArray *_words; NSMutableArray *_wrong; NSString *_title; NSInteger _index; UITextField *_answer; UILabel *_prompt; UILabel *_status;
}
@end
@implementation VocabController
- (NSString *)dir { NSArray *a=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES); return [a objectAtIndex:0]; }
- (void)loadBooks { [_books release]; _books=[[NSMutableArray alloc]init]; NSArray *files=[[NSFileManager defaultManager]contentsOfDirectoryAtPath:[self dir] error:nil]; for(NSString *f in files)if([[f pathExtension]isEqualToString:@"vocab"])[_books addObject:f]; }
- (void)viewDidLoad { [super viewDidLoad]; self.title=@"Vocabulary6"; _wrong=[[NSMutableArray alloc]init]; [self loadBooks]; self.navigationItem.rightBarButtonItem=[[[UIBarButtonItem alloc]initWithTitle:@"오답" style:UIBarButtonItemStyleBordered target:self action:@selector(review)]autorelease]; }
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s { return [_books count]; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { UITableViewCell *c=[t dequeueReusableCellWithIdentifier:@"book"]; if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"book"]autorelease]; c.textLabel.text=[[_books objectAtIndex:p.row]stringByDeletingPathExtension]; c.accessoryType=UITableViewCellAccessoryDisclosureIndicator; return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { NSString *f=[_books objectAtIndex:p.row]; NSData *d=[NSData dataWithContentsOfFile:[[self dir]stringByAppendingPathComponent:f]]; NSDictionary *obj=[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]; NSArray *w=[obj objectForKey:@"words"]; if(![w isKindOfClass:[NSArray class]]||![w count]){ [[[UIAlertView alloc]initWithTitle:@"오류" message:@"단어장 형식을 확인하세요." delegate:nil cancelButtonTitle:@"확인" otherButtonTitles:nil]show];return; } [_words release];_words=[w mutableCopy];_index=0;[_wrong removeAllObjects];[self quiz]; }
- (void)review { if(![_wrong count]){ [[[UIAlertView alloc]initWithTitle:@"오답 없음" message:nil delegate:nil cancelButtonTitle:@"확인" otherButtonTitles:nil]show];return;} [_words release];_words=[_wrong mutableCopy];_index=0;[_wrong removeAllObjects];[self quiz]; }
- (void)quiz { UIViewController *v=[[[UIViewController alloc]init]autorelease]; v.title=@"뜻 시험"; v.view.backgroundColor=[UIColor groupTableViewBackgroundColor]; CGRect b=v.view.bounds; _prompt=[[[UILabel alloc]initWithFrame:CGRectMake(20,80,b.size.width-40,70)]autorelease];_prompt.backgroundColor=[UIColor clearColor];_prompt.textAlignment=UITextAlignmentCenter;_prompt.font=[UIFont boldSystemFontOfSize:26];_prompt.autoresizingMask=UIViewAutoresizingFlexibleWidth;[v.view addSubview:_prompt]; _answer=[[[UITextField alloc]initWithFrame:CGRectMake(20,170,b.size.width-40,42)]autorelease];_answer.borderStyle=UITextBorderStyleRoundedRect;_answer.placeholder=@"한국어 뜻 입력";_answer.returnKeyType=UIReturnKeyDone;_answer.delegate=self;_answer.autoresizingMask=UIViewAutoresizingFlexibleWidth;[v.view addSubview:_answer]; UIButton *btn=[UIButton buttonWithType:UIButtonTypeRoundedRect];btn.frame=CGRectMake(20,225,b.size.width-40,44);btn.autoresizingMask=UIViewAutoresizingFlexibleWidth;[btn setTitle:@"채점" forState:UIControlStateNormal];[btn addTarget:self action:@selector(check) forControlEvents:UIControlEventTouchUpInside];[v.view addSubview:btn];_status=[[[UILabel alloc]initWithFrame:CGRectMake(20,285,b.size.width-40,75)]autorelease];_status.backgroundColor=[UIColor clearColor];_status.textAlignment=UITextAlignmentCenter;_status.numberOfLines=3;_status.autoresizingMask=UIViewAutoresizingFlexibleWidth;[v.view addSubview:_status];[self.navigationController pushViewController:v animated:YES];[self next]; }
- (void)next { if(_index>=[_words count]){_prompt.text=@"시험 완료";_status.text=[NSString stringWithFormat:@"오답 %lu개",(unsigned long)[_wrong count]];_answer.hidden=YES;return;} NSDictionary *w=[_words objectAtIndex:_index];_prompt.text=[w objectForKey:@"word"];_status.text=[NSString stringWithFormat:@"%ld / %lu",(long)(_index+1),(unsigned long)[_words count]];_answer.text=@"";_answer.hidden=NO; }
- (NSString *)norm:(NSString *)s { NSMutableString *v=[NSMutableString string];for(NSUInteger i=0;i<[s length];i++){unichar c=[s characterAtIndex:i];if(![[NSCharacterSet whitespaceAndNewlineCharacterSet]characterIsMember:c]&&![[NSCharacterSet punctuationCharacterSet]characterIsMember:c])[v appendFormat:@"%C",c];}return v; }
- (BOOL)textFieldShouldReturn:(UITextField *)f { [self check];return YES; }
- (void)check { if(_index>=[_words count])return;NSDictionary *w=[_words objectAtIndex:_index];id meanings=[w objectForKey:@"meanings"];if(![meanings isKindOfClass:[NSArray class]])meanings=[NSArray arrayWithObject:([w objectForKey:@"meaning"]?:@"")];BOOL ok=NO;for(NSString *m in meanings)if([[self norm:m]isEqualToString:[self norm:_answer.text]])ok=YES;[_answer resignFirstResponder];if(!ok)[_wrong addObject:w];NSString *msg=ok?@"정답":@"오답";NSString *detail=[meanings componentsJoinedByString:@", "];UIAlertView *a=[[[UIAlertView alloc]initWithTitle:msg message:detail delegate:self cancelButtonTitle:@"다음" otherButtonTitles:ok?nil:@"정답 인정",nil]autorelease];[a show]; }
- (void)alertView:(UIAlertView *)a clickedButtonAtIndex:(NSInteger)i { if(i==1&&[_wrong count])[_wrong removeLastObject];_index++;[self next]; }
- (void)dealloc { [_books release];[_words release];[_wrong release];[super dealloc]; }
@end
@interface AppDelegate : UIResponder <UIApplicationDelegate> { UIWindow *_window; UINavigationController *_nav; } @end
@implementation AppDelegate
- (BOOL)application:(UIApplication *)app didFinishLaunchingWithOptions:(NSDictionary *)opts { NSString *dir=[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES)objectAtIndex:0];NSString *dst=[dir stringByAppendingPathComponent:@"Cheonjae3.vocab"];if(![[NSFileManager defaultManager]fileExistsAtPath:dst])[[NSFileManager defaultManager]copyItemAtPath:[[NSBundle mainBundle]pathForResource:@"Cheonjae3" ofType:@"vocab"] toPath:dst error:nil];_window=[[UIWindow alloc]initWithFrame:[[UIScreen mainScreen]bounds]];_nav=[[UINavigationController alloc]initWithRootViewController:[[[VocabController alloc]initWithStyle:UITableViewStyleGrouped]autorelease]];_window.rootViewController=_nav;[_window makeKeyAndVisible];return YES; }
- (BOOL)application:(UIApplication *)app openURL:(NSURL *)url sourceApplication:(NSString *)source annotation:(id)annotation { if(![[[url path]pathExtension]isEqualToString:@"vocab"])return NO;NSString *dest=[[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES)objectAtIndex:0]stringByAppendingPathComponent:[url lastPathComponent]];[[NSFileManager defaultManager]removeItemAtPath:dest error:nil];BOOL ok=[[NSFileManager defaultManager]copyItemAtURL:url toURL:[NSURL fileURLWithPath:dest] error:nil];[(_nav.topViewController) performSelector:@selector(loadBooks)];[(UITableViewController *)_nav.topViewController.tableView reloadData];return ok; }
- (void)dealloc { [_nav release];[_window release];[super dealloc]; }
@end
int main(int argc,char **argv){NSAutoreleasePool *p=[[NSAutoreleasePool alloc]init];int r=UIApplicationMain(argc,argv,nil,NSStringFromClass([AppDelegate class]));[p release];return r;}
